import torch
import torch.nn as nn

class ModelNew(nn.Module):
    """
    Performs a transposed 1D convolution operation with asymmetric input and square kernel.
    Supports padding, striding, and dilation.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (int): Size of the square convolution kernel.
        stride (int, optional): Stride of the convolution. Defaults to 1.
        padding (int, optional): Padding applied to the input. Defaults to 0.
        dilation (int, optional): Spacing between kernel elements. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        # Custom CUDA operator for transposed convolution
        self.transposed_conv = torch.nn.functional.transpose_conv2d(
            in_channels, out_channels, kernel_size, stride=stride, padding=padding, dilation=dilation, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the transposed 1D convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, length).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, length_out).
        """
        return self.transposed_conv(x)

# Define the custom CUDA kernel for transposed convolution
transposed_conv_kernel = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void transposed_conv2d_kernel(
    float* input,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    // Calculate the number of elements to process
    int total_elements = batch_size * in_channels * kernel_size * stride * (kernel_size + 2 * padding - 1) / (stride * stride);

    // Calculate the block size and number of blocks
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    // Initialize output array
    float* out = nullptr;
    if (!out) {
        out = torch::zeros_like(input);
    }

    // Calculate the starting index for each block
    int start_idx = blockIdx.x * blockDim.x;

    // Loop over all elements in the input tensor
    for (int i = 0; i < total_elements; i += block_size) {
        // Calculate the global index within the current block
        int idx = start_idx + i;

        // Determine the position within the kernel
        int k_index = (idx / (kernel_size * stride)) % (kernel_size);
        int offset_in_kernel = (idx % (kernel_size * stride)) - (k_index * stride);

        // Apply transposed convolution operation
        float val = input[idx] * dilation;
        if (offset_in_kernel < 0) {
            offset_in_kernel += kernel_size * stride;
        }

        // Calculate the output position
        int out_idx = k_index + offset_in_kernel;

        // Store the result in the output tensor
        out[out_idx] = val;
    }

    return out;
}
"""

